# Get all registrations with partners and table assignments registrations = records.registration_ids.filtered(lambda r: r.partner_id and (r.session_1_table_id or r.session_2_table_id or r.session_3_table_id))
if not registrations: raise UserError("No table assignments found for this event.")
# Call the report on registrations action = env.ref('membership_network.event_table_assignment_glabel').report_action(registrations)
